-- A32: contêiner interno e versionado de regra econômica; não aceita valores, percentuais, parcelas, pagamento, cobrança, repasse ou integração externa.
create table public.subdivision_economic_rule_sets (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,development_id uuid not null,version_reference text not null check(version_reference ~ '^[A-Z][A-Z0-9_]{2,79}$'),working_state text not null check(working_state in ('draft_internal','review_required')),created_by uuid not null references public.identity_subjects(user_id) on delete restrict,created_at timestamptz not null default now(),constraint subdivision_economic_rule_sets_development_fk foreign key(development_id,organization_id) references public.subdivision_developments(id,organization_id) on delete restrict,constraint subdivision_economic_rule_sets_unique unique(organization_id,development_id,version_reference));
alter table public.subdivision_economic_rule_sets enable row level security;revoke all on table public.subdivision_economic_rule_sets from public,anon,authenticated;
comment on table public.subdivision_economic_rule_sets is 'A32: referência interna e versionada de regras econômicas; sem cálculo, valores, percentuais, parcelas, cobrança, pagamento, repasse ou integração externa.';
create or replace function public.subdivision_create_economic_rule_set(p_actor_user_id uuid,p_organization_id uuid,p_module public.operating_module,p_purpose_code text,p_development_id uuid,p_version_reference text,p_working_state text,p_correlation_id uuid) returns uuid language plpgsql security definer set search_path='' as $$ declare v_existing uuid;v_rule_set_id uuid;begin perform private.require_subdivision_draft_authority(p_actor_user_id,p_organization_id,p_module,p_purpose_code);select target_id into v_existing from public.admin_audit_events where command_name='subdivision_create_economic_rule_set' and correlation_id=p_correlation_id and outcome='allowed' order by occurred_at desc limit 1;if v_existing is not null then return v_existing;end if;if not exists(select 1 from public.subdivision_developments where id=p_development_id and organization_id=p_organization_id) then raise exception using errcode='42501',message='SUBDIVISION_ECONOMIC_RULE_SET_CONTEXT_DENIED';end if;insert into public.subdivision_economic_rule_sets(organization_id,development_id,version_reference,working_state,created_by)values(p_organization_id,p_development_id,trim(upper(p_version_reference)),p_working_state,p_actor_user_id)on conflict(organization_id,development_id,version_reference)do update set working_state=excluded.working_state,created_by=excluded.created_by returning id into v_rule_set_id;insert into public.admin_audit_events(correlation_id,actor_user_id,organization_id,command_name,outcome,target_type,target_id,payload_redacted)values(p_correlation_id,p_actor_user_id,p_organization_id,'subdivision_create_economic_rule_set','allowed','subdivision_economic_rule_set',v_rule_set_id,jsonb_build_object('module',p_module::text,'purpose_code',trim(p_purpose_code),'working_state',p_working_state,'economic_rule_set',true));return v_rule_set_id;end;$$;
revoke all on function public.subdivision_create_economic_rule_set(uuid,uuid,public.operating_module,text,uuid,text,text,uuid) from public,anon,authenticated;grant execute on function public.subdivision_create_economic_rule_set(uuid,uuid,public.operating_module,text,uuid,text,text,uuid) to service_role;
create or replace function public.subdivision_list_economic_rule_sets(p_actor_user_id uuid,p_organization_id uuid,p_module public.operating_module,p_purpose_code text) returns table(economic_rule_set_id uuid,development_id uuid,version_reference text,working_state text,created_at timestamptz) language plpgsql security definer set search_path='' as $$ begin perform private.require_subdivision_draft_authority(p_actor_user_id,p_organization_id,p_module,p_purpose_code);return query select id,development_id,version_reference,working_state,created_at from public.subdivision_economic_rule_sets where organization_id=p_organization_id order by created_at desc;end;$$;
revoke all on function public.subdivision_list_economic_rule_sets(uuid,uuid,public.operating_module,text) from public,anon,authenticated;grant execute on function public.subdivision_list_economic_rule_sets(uuid,uuid,public.operating_module,text) to service_role;
